function processData(data) {
  const result = data.map(item => {
    return { ...item, processed: true, timestamp: Date.now() };
  });
  return result;
}
class DataManager {
  constructor(name) { this.name = name; this.storage = []; }
  addItem(item) { this.storage.push(item); }
}

